 | journal = Software: Practice and Experience
 | volume = 25
 | issue = 12
 | pages = 1315–1330
 | publisher = John Wiley & Sons, Inc.
 | location = New York, NY, USA
 | date = December 1995
 | url = https://www.cs.tufts.edu/comp/150FP/archive/hans-boehm/ropes.pdf
